const w=[[0,30],[30,60],[60,90],[90,120]];
for (const [a,b] of w){
  const c=canary.filter(r=>r.t>=a&&r.t<b), s=stable.filter(r=>r.t>=a&&r.t<b);
  print(`win ${a}-${b}s | canary n=${c.length} p50=${pct(c.map(r=>r.ms),50)} p95=${pct(c.map(r=>r.ms),95)} p99=${pct(c.map(r=>r.ms),99)} 5xx=${c.filter(r=>r.status>=500).length} | stable n=${s.length} p50=${pct(s.map(r=>r.ms),50)} p95=${pct(s.map(r=>r.ms),95)} p99=${pct(s.map(r=>r.ms),99)} 5xx=${s.filter(r=>r.status>=500).length}`);
}
print('total 5xx canary=', canary.filter(r=>r.status>=500).length, ' stable=', stable.filter(r=>r.status>=500).length);
print('statuses canary:', JSON.stringify(canary.reduce((m,r)=>{m[r.status]=(m[r.status]||0)+1;return m;},{})));
print('statuses stable:', JSON.stringify(stable.reduce((m,r)=>{m[r.status]=(m[r.status]||0)+1;return m;},{})));
const paths=[...new Set(rows.map(r=>r.path))];
for(const p of paths){
  const c=canary.filter(r=>r.path===p&&r.t>=60), s=stable.filter(r=>r.path===p&&r.t>=60);
  print(`last60s ${p} canary n=${c.length} p95=${pct(c.map(r=>r.ms),95)} | stable n=${s.length} p95=${pct(s.map(r=>r.ms),95)}`);
}
const cEarly=canary.filter(r=>r.t<30).map(r=>r.ms), cLate=canary.filter(r=>r.t>=60).map(r=>r.ms);
print('canary p95 first30=',pct(cEarly,95),' last60=',pct(cLate,95));
print('canary max t=', Math.max(...canary.map(r=>r.t)).toFixed(1));

const cm=canary.map(r=>r.ms), sm=stable.map(r=>r.ms);
print('CONVENTION CHECK');
print('canary frac  p50/p95/p99 =', pct(cm,0.5), pct(cm,0.95), pct(cm,0.99), ' max=', Math.max(...cm));
print('canary int   p50/p95/p99 =', pct(cm,50), pct(cm,95), pct(cm,99));
print('stable frac  p50/p95/p99 =', pct(sm,0.5), pct(sm,0.95), pct(sm,0.99), ' max=', Math.max(...sm));
print('counts canary/stable =', canary.length, stable.length, 'total', rows.length);
print('5xx canary/stable =', canary.filter(r=>r.status>=500).length, stable.filter(r=>r.status>=500).length);

const paths=[...new Set(rows.map(r=>r.path))].sort();
print('PATHS (whole test, fraction convention)');
for(const p of paths){
  const c=canary.filter(r=>r.path===p).map(r=>r.ms), s=stable.filter(r=>r.path===p).map(r=>r.ms);
  print(p+' | canary n='+c.length+' p50='+pct(c,0.5)+' p95='+pct(c,0.95)+' p99='+pct(c,0.99)+' || stable n='+s.length+' p50='+pct(s,0.5)+' p95='+pct(s,0.95)+' p99='+pct(s,0.99));
}

print('WINDOWS 30s (fraction convention)');
for(const [a,b] of [[0,30],[30,60],[60,90],[90,120]]){
  const c=canary.filter(r=>r.t>=a&&r.t<b).map(r=>r.ms), s=stable.filter(r=>r.t>=a&&r.t<b).map(r=>r.ms);
  print('win '+a+'-'+b+'s | canary n='+c.length+' p50='+pct(c,0.5)+' p95='+pct(c,0.95)+' | stable n='+s.length+' p50='+pct(s,0.5)+' p95='+pct(s,0.95));
}

print('FINE WINDOWS 10s canary p95 vs stable p95');
for(let a=0;a<120;a+=10){
  const c=canary.filter(r=>r.t>=a&&r.t<a+10).map(r=>r.ms), s=stable.filter(r=>r.t>=a&&r.t<a+10).map(r=>r.ms);
  print(a+'-'+(a+10)+'s canary n='+c.length+' p95='+pct(c,0.95)+' | stable n='+s.length+' p95='+pct(s,0.95));
}

print('LAST 60s PER PATH (steady state)');
for(const p of paths){
  const c=canary.filter(r=>r.path===p&&r.t>=60).map(r=>r.ms), s=stable.filter(r=>r.path===p&&r.t>=60).map(r=>r.ms);
  print(p+' | canary n='+c.length+' p50='+pct(c,0.5)+' p95='+pct(c,0.95)+' p99='+pct(c,0.99)+' || stable n='+s.length+' p50='+pct(s,0.5)+' p95='+pct(s,0.95)+' p99='+pct(s,0.99));
}
const cl=canary.filter(r=>r.t>=60).map(r=>r.ms), sl=stable.filter(r=>r.t>=60).map(r=>r.ms);
print('LAST60 ALL | canary p50='+pct(cl,0.5)+' p95='+pct(cl,0.95)+' p99='+pct(cl,0.99)+' | stable p50='+pct(sl,0.5)+' p95='+pct(sl,0.95)+' p99='+pct(sl,0.99));
const cf=canary.filter(r=>r.t<30).map(r=>r.ms), sf=stable.filter(r=>r.t<30).map(r=>r.ms);
print('FIRST30 ALL | canary p95='+pct(cf,0.95)+' | stable p95='+pct(sf,0.95));
print('statuses canary', JSON.stringify(canary.reduce((o,r)=>(o[r.status]=(o[r.status]||0)+1,o),{})));
print('statuses stable', JSON.stringify(stable.reduce((o,r)=>(o[r.status]=(o[r.status]||0)+1,o),{})));

